function worldTravelHint(){
  if(!S.hero)return '';
  const here=heroZone(),rows=QUESTS.filter((q,i)=>qState(q.k)!==3&&qVisible(i)&&PLACES[qPlace(q)]&&ZONES[qZone(q)]&&PLACES[ZONES[qZone(q)].entry]?.z===qZone(q));
  const active=rows.filter(q=>qZone(q)!==here&&(qState(q.k)===1||qState(q.k)===2));
  const elsewhere=rows.filter(q=>qZone(q)!==here);
  const targets=active.length?active:!rows.some(q=>qZone(q)===here)?elsewhere:[];
  if(!targets.length)return '';
  const names=[...new Set(targets.map(q=>ZONES[qZone(q)].name))].join(', ');
  return active.length?'Квест ведёт в другую зону: '+names:'Здесь нет доступных заданий. Задания есть: '+names;
}
